import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Reporting and output audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/REPORTING-OUTPUTS.html"}],["meta",{"property":"og:title","content":"Reporting and output audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/REPORTING-OUTPUTS.html"}],["meta",{"name":"twitter:title","content":"Reporting and output audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/REPORTING-OUTPUTS.md","filePath":"audits/REPORTING-OUTPUTS.md","lastUpdated":1794184492000}`),a={name:`audits/REPORTING-OUTPUTS.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="reporting-and-output-audit" tabindex="-1">Reporting and output audit <a class="header-anchor" href="#reporting-and-output-audit" aria-label="Permalink to “Reporting and output audit”">​</a></h1><h2 id="fin-01-—-final-value-is-not-the-closing-portfolio-value-after-withdrawals" tabindex="-1">FIN-01 — “Final value” is not the closing portfolio value after withdrawals <a class="header-anchor" href="#fin-01-—-final-value-is-not-the-closing-portfolio-value-after-withdrawals" aria-label="Permalink to “FIN-01 — “Final value” is not the closing portfolio value after withdrawals”">​</a></h2><p><strong>Severity: P1</strong></p><p><strong>Evidence:</strong></p><ul><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/simulation-runtime.js#L517-L523" target="_blank" rel="noreferrer">SimulationRuntime.buildResult L517-L523</a> sets <code>total_principal</code> to original capital plus all inflows.</li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/results.js#L66-L72" target="_blank" rel="noreferrer">SimResult L66-L72</a> defines <code>cash_retained</code>, <code>cash_flow_net_worth</code> and <code>final_value</code>. The <code>final_value</code> formula is contributed capital plus gross interest minus fees and AIT; it does not subtract paid outflows.</li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L110-L114" target="_blank" rel="noreferrer">Web result metrics L110-L114</a> displays <code>final_value_after_ait</code> as “Final value”.</li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/reporting/html.js#L297-L300" target="_blank" rel="noreferrer">HTML report L297-L300</a> labels <code>result.final_value</code> as “Final simulated portfolio value”.</li></ul><p><strong>Impact:</strong> when scheduled outflows have been paid, the displayed “Final value” can exceed the assets remaining at the end of the simulation by the amount already withdrawn. The current formula is a pre-withdrawal contribution-plus-return measure, not the closing portfolio balance. The distinction matters when users compare a plan with different withdrawal schedules.</p><p><strong>Recommendation:</strong> define separate, unambiguous measures:</p><ul><li><code>contributed_capital</code>: opening capital plus inflows.</li><li><code>pre_withdrawal_value</code>: contributed capital plus return after AIT/fees, before paid outflows.</li><li><code>closing_assets</code>: actual cash and any still-active investments at the simulation boundary.</li><li><code>outstanding_liabilities</code>: unpaid outflows.</li><li><code>closing_net_worth</code>: closing assets less outstanding liabilities.</li></ul><p>For the scoped mode, reconcile the closing value against ending account balances and outstanding obligations. Update UI, console and HTML labels together. Do not change the existing <code>final_value</code> contract until all consumers and XIRR calculations are reviewed.</p><p><strong>Regression case:</strong> start with LKR 100,000, no interest, pay a LKR 40,000 outflow, finish with LKR 60,000. The report must not label LKR 100,000 as the closing portfolio value. Add a second case with interest, fees and an unpaid deferred outflow.</p><h2 id="reporting-strengths" tabindex="-1">Reporting strengths <a class="header-anchor" href="#reporting-strengths" aria-label="Permalink to “Reporting strengths”">​</a></h2><ul><li>Dynamic text in tables, ledger rows, decision cards and product labels is generally passed through the HTML escaping helper in <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/reporting/html.js" target="_blank" rel="noreferrer">html.js</a>.</li><li>Embedded chart JSON escapes closing-script sequences before insertion.</li><li>The standalone report template embeds its CSS and JavaScript; no external script fetch is required by the reviewed template.</li><li>The report includes chart-data tables as a non-canvas fallback, an event ledger, transfer/booking instructions, AIT breakdowns and product eligibility caveats.</li><li>The report uses explicit LKR units and separates gross interest, AIT and transfer fees in its reconciliation panel.</li><li>The report preserves the financial warnings and outstanding-outflow status.</li></ul><h2 id="additional-observations" tabindex="-1">Additional observations <a class="header-anchor" href="#additional-observations" aria-label="Permalink to “Additional observations”">​</a></h2><h3 id="fin-02-—-capital-invested-is-broader-than-the-actual-fd-principal-booked" tabindex="-1">FIN-02 — “Capital invested” is broader than the actual FD principal booked <a class="header-anchor" href="#fin-02-—-capital-invested-is-broader-than-the-actual-fd-principal-booked" aria-label="Permalink to “FIN-02 — “Capital invested” is broader than the actual FD principal booked”">​</a></h3><p>The web metric reads <code>total_principal</code>, which the runtime sets to opening capital plus all inflows. That is capital contributed/available over the horizon, not necessarily the sum of principal actually placed into fixed deposits. Rename the metric to “Capital contributed” or add a separate actual-FD-principal total.</p><h3 id="fin-03-—-the-report-needs-source-provenance-beside-each-simulated-product" tabindex="-1">FIN-03 — The report needs source provenance beside each simulated product <a class="header-anchor" href="#fin-03-—-the-report-needs-source-provenance-beside-each-simulated-product" aria-label="Permalink to “FIN-03 — The report needs source provenance beside each simulated product”">​</a></h3><p>The product report includes name, rate, tenor, payout and catalogue eligibility, but not the source URL, source effective date, research status or source type. See <a href="./DATA-AND-FINANCIAL-ASSUMPTIONS.html#data-01-source-provenance-is-not-visible-in-the-simulation">DATA-01</a>.</p><h3 id="qa-rep-01-—-test-the-actual-downloaded-html-not-only-string-fragments" tabindex="-1">QA-REP-01 — Test the actual downloaded HTML, not only string fragments <a class="header-anchor" href="#qa-rep-01-—-test-the-actual-downloaded-html-not-only-string-fragments" aria-label="Permalink to “QA-REP-01 — Test the actual downloaded HTML, not only string fragments”">​</a></h3><p>The tests assert report markup, chart JSON and token contracts, but a browser test should open the downloaded report offline and verify chart initialization, collapsible tables, long content, print layout, keyboard access and no external network dependency.</p><h2 id="recommended-changes" tabindex="-1">Recommended changes <a class="header-anchor" href="#recommended-changes" aria-label="Permalink to “Recommended changes”">​</a></h2><ol><li>Fix FIN-01 semantics before changing visual styling.</li><li>Rename the capital metric.</li><li>Add a product-source panel and report metadata.</li><li>Add report download/open tests with representative large and adversarial labels.</li><li>Verify print/PDF layout and standalone offline behaviour in a browser.</li></ol>`,21)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};